import { cacheLife, cacheTag, revalidateTag } from 'next/cache'
import { getAllProducts } from '../lib/db'

async function getCatalog() {
  'use cache'
  cacheTag('products')
  cacheLife('max')
  return getAllProducts()
}

export default async function Page() {
  async function syncLatestCatalog() {
    'use server'
    // Mark catalog data stale so admins keep working immediately.
    // Fresh ERP/PIM data fills in in the background across tagged views.
    revalidateTag('products', 'max')
  }

  const products = await getCatalog()

  return (
    <main>
      <h1>Product catalog</h1>
      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} — ${product.price}
          </li>
        ))}
      </ul>
    </main>
  )
}
